        (528, 2317, 'Réactions indésirables', 'S.O.'),
        (529, 2496, 'Mises en garde', 'Do not use if you are pregnant or breastfeeding. Consult a health care practitioner if symptoms worsen. Do not use if security seal is missing or broken. Store in a cool, dry place away from direct sunlight. Keep out of reach of children.'),
        (530, 2541, 'Mises en garde', 'If you are taking blood thinners, consult a health care practitioner prior to use.'),
        (531, 2700, 'Contre-indications', 'S.O.'),
        (532, 2700, 'Mises en garde', 'S.O.'),
        (533, 2426, 'Contre-indications', 'S.O.'),
