        (620, 2373, 'Mises en garde', 'If symptoms persist or worsen, or if new symptoms develop, discontinue use and consult a health care practitioner. If you are taking prescription medications, consult a health care practitioner prior to use.'),
        (621, 2373, 'Contre-indications', 'If you are pregnant or breastfeeding, do not use this product.'),
        (622, 2551, 'Contre-indications', 'If you are pregnant or breastfeeding, do not use this product. If you have broken, irritated, or sensitive skin, do not use this product.'),
